const msg = $input.first().json.message || {};
const text = (msg.text || '').trim();
const chatId = msg.chat?.id;
const name = msg.from?.first_name || 'amigo';
const username = msg.from?.username || name;
const userId = msg.from?.id;
const lower = text.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '');

// ===== HELPER: Distancia de Levenshtein =====
function levenshtein(a, b) {
  const m = [];
  for (let i = 0; i <= b.length; i++) m[i] = [i];
  for (let j = 0; j <= a.length; j++) m[0][j] = j;
  for (let i = 1; i <= b.length; i++)
    for (let j = 1; j <= a.length; j++)
      m[i][j] = Math.min(m[i-1][j]+1, m[i][j-1]+1, m[i-1][j-1]+(a[j-1]===b[i-1]?0:1));
  return m[b.length][a.length];
}

function fuzzy(input, keywords, threshold) {
  threshold = threshold || 0.35;
  const norm = input.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '');
  const words = norm.split(/\s+/);
  for (const kw of keywords) {
    const nkw = kw.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '');
    if (norm.includes(nkw)) return true;
    for (const w of words) {
      if (w.length < 3) continue;
      const dist = levenshtein(w, nkw);
      const maxL = Math.max(w.length, nkw.length);
      if (1 - dist/maxL >= 1 - threshold) return true;
    }
  }
  return false;
}

// ===== COMANDOS =====
if (text.startsWith('/')) {
  const cmd = lower.split(' ')[0].replace(/@.*/,'').split('/')[1];

  if (cmd === 'start') {
    return [{ json: { chatId, type: 'static', text: `🎮 <b>¡Bienvenido a ApexTournament, ${name}!</b>\n\nSoy tu asistente de torneos eSports. ¡Hablame como si fuera un amigo! 😊\n\n💬 <b>Puedes escribirme lo que sea:</b>\n• \"Qué torneos hay\"\n• \"Quién va ganando\"\n• \"Cuéntame un chiste gamer\"\n• \"Qué opinas de Apex Legends\"\n\n<b>📋 Comandos rápidos:</b>\n/torneos /ranking /stats /proximas /juegos /ayuda` }}];
  }
  if (cmd === 'ayuda' || cmd === 'help') {
    return [{ json: { chatId, type: 'static', text: `📖 <b>ApexTournament Bot</b>\n\n🤖 <b>¡Soy conversacional!</b> Háblame normal, no necesitas comandos.\n\n<b>Comandos disponibles:</b>\n/torneos - Torneos activos\n/ranking - Top jugadores\n/stats - Tus estadísticas\n/proximas - Próximas partidas\n/envivo - En vivo\n/clanes - Equipos\n/miclan - Tu clan\n/juegos - Juegos\n/reglas - Normas\n\n<b>💡 O simplemente pregúntame lo que quieras.</b>` }}];
  }
  if (cmd === 'reglas') {
    return [{ json: { chatId, type: 'static', text: `📜 <b>Reglas de ApexTournament</b>\n\n1️⃣ Respeto a todos\n2️⃣ Fair play siempre\n3️⃣ Estar 15 min antes de la partida\n4️⃣ Tolerancia cero a trampas\n5️⃣ Administradores tienen la última palabra\n\n<i>¿Dudas? Pregúntame.</i>` }}];
  }
  if (['torneos','ranking','juegos','proximas','envivo','stats','clanes','miclan'].includes(cmd)) {
    return [{ json: { chatId, type: 'db', query: cmd, userId } }];
  }
  // Comando no reconocido → enviarlo a la IA para que interprete
  return [{ json: { chatId, type: 'ai', text: text, userId, name, username } }];
}

// ===== TODO MENSAJE NO-COMANDO → IA =====
// Ya no necesitamos patrones rígidos, la IA se encarga de todo
return [{ json: { chatId, type: 'ai', text: text, userId, name, username } }];

const data = $input.first().json;
const query = data.query;
const userId = data.userId;

const queries = {
  torneos: "SELECT t.name, t.status, t.start_date, t.prize_pool, g.name as game_name FROM tournaments t LEFT JOIN games g ON t.game_id = g.id WHERE t.status IN ('REGISTRATION_OPEN', 'PUBLISHED', 'IN_PROGRESS') ORDER BY t.start_date ASC LIMIT 10",
  ranking: "SELECT ps.rating, ps.wins, ps.losses, u.username, g.name as game_name FROM player_stats ps JOIN users u ON ps.user_id = u.id JOIN games g ON ps.game_id = g.id ORDER BY ps.rating DESC LIMIT 10",
  juegos: "SELECT name, team_size_default FROM games ORDER BY name ASC",
  proximas: "SELECT m.scheduled_datetime, t.name as tournament_name, ht.name as home_team, at2.name as away_team FROM matches m JOIN tournaments t ON m.tournament_id = t.id LEFT JOIN teams ht ON m.home_team_id = ht.id LEFT JOIN teams at2 ON m.away_team_id = at2.id WHERE m.status = 'SCHEDULED' AND m.scheduled_datetime >= NOW() ORDER BY m.scheduled_datetime ASC LIMIT 5",
  envivo: "SELECT m.home_score, m.away_score, t.name as tournament_name, ht.name as home_team, at2.name as away_team FROM matches m JOIN tournaments t ON m.tournament_id = t.id LEFT JOIN teams ht ON m.home_team_id = ht.id LEFT JOIN teams at2 ON m.away_team_id = at2.id WHERE m.status = 'LIVE' LIMIT 10",
  stats: `SELECT u.username, ps.rating, ps.wins, ps.losses, g.name as game_name FROM users u LEFT JOIN player_stats ps ON ps.user_id = u.id LEFT JOIN games g ON ps.game_id = g.id WHERE u.telegram_chat_id = '${userId}' LIMIT 20`,
  clanes: "SELECT c.name, c.tag, u.username as leader_name, (SELECT COUNT(*) FROM clan_members WHERE clan_id = c.id) as member_count FROM clans c JOIN users u ON c.leader_id = u.id ORDER BY c.created_at DESC LIMIT 10",
  miclan: `SELECT c.name, c.tag, cm.role, cm.joined_at FROM users u JOIN clan_members cm ON cm.user_id = u.id JOIN clans c ON cm.clan_id = c.id WHERE u.telegram_chat_id = '${userId}' LIMIT 1`
};

return [{ json: { sql: queries[query] || 'SELECT 1', query, chatId: data.chatId, userId } }];

const queryType = $('Build Query').first().json.query;
const rows = $input.all().map(i => i.json);

let msg = '';

switch(queryType) {
  case 'torneos': {
    if (rows.length === 0 || !rows[0].name) { msg = '😔 No hay torneos activos en este momento.'; break; }
    msg = '🏆 <b>Torneos Disponibles:</b>\n\n';
    rows.forEach(t => {
      const emoji = t.status === 'IN_PROGRESS' ? '🔴' : t.status === 'REGISTRATION_OPEN' ? '🟢' : '🟡';
      const st = t.status === 'IN_PROGRESS' ? 'En Curso' : t.status === 'REGISTRATION_OPEN' ? 'Registro Abierto' : 'Próximamente';
      msg += `${emoji} <b>${t.name}</b>\n   🎮 ${t.game_name||'Varios'} | 💰 $${t.prize_pool||0} | ${st}\n\n`;
    });
    break;
  }
  case 'ranking': {
    if (rows.length === 0 || !rows[0].username) { msg = '😔 No hay jugadores en el ranking.'; break; }
    const medals = ['🥇','🥈','🥉'];
    msg = '🏅 <b>Top 10 Jugadores:</b>\n\n';
    rows.forEach((s,i) => {
      const m = medals[i] || `${i+1}.`;
      const wr = s.wins+s.losses > 0 ? Math.round((s.wins/(s.wins+s.losses))*100) : 0;
      msg += `${m} <b>${s.username}</b> ⭐${s.rating} | ${s.wins}W/${s.losses}L (${wr}%)\n`;
    });
    break;
  }
  case 'juegos': {
    if (rows.length === 0 || !rows[0].name) { msg = '😔 No hay juegos registrados.'; break; }
    msg = '🎮 <b>Juegos Disponibles:</b>\n\n';
    rows.forEach(g => { msg += `• <b>${g.name}</b> (${g.team_size_default} jugadores)\n`; });
    break;
  }
  case 'proximas': {
    if (rows.length === 0 || !rows[0].tournament_name) { msg = '📅 No hay partidas programadas.'; break; }
    msg = '⚔️ <b>Próximas Partidas:</b>\n\n';
    rows.forEach(m => {
      const time = m.scheduled_datetime ? new Date(m.scheduled_datetime).toLocaleString('es-MX',{dateStyle:'short',timeStyle:'short'}) : 'TBD';
      msg += `🏆 <b>${m.tournament_name}</b>\n   ${m.home_team||'TBD'} 🆚 ${m.away_team||'TBD'} | 🕐 ${time}\n\n`;
    });
    break;
  }
  case 'envivo': {
    if (rows.length === 0 || !rows[0].tournament_name) { msg = '📺 No hay partidas en vivo.\nUsa /proximas.'; break; }
    msg = '🔴 <b>EN VIVO:</b>\n\n';
    rows.forEach(m => { msg += `🏆 ${m.tournament_name}: ${m.home_team||'TBD'} <b>${m.home_score||0}-${m.away_score||0}</b> ${m.away_team||'TBD'}\n`; });
    break;
  }
  case 'stats': {
    if (rows.length === 0 || !rows[0].username) { msg = '📊 <b>Estadísticas</b>\n\n❌ Tu cuenta no está vinculada.\n\n1. Abre ApexTournament\n2. Ve a Configuración → Notificaciones\n3. Conecta tu Telegram'; break; }
    const u = rows[0];
    let tw=0,tl=0,tr=0;
    rows.filter(r=>r.rating).forEach(s=>{tw+=s.wins||0;tl+=s.losses||0;tr=Math.max(tr,s.rating||0);});
    const wr = tw+tl>0 ? Math.round((tw/(tw+tl))*100) : 0;
    msg = `📊 <b>Estadísticas de ${u.username}</b>\n\n⭐ Rating: ${tr} | 🏆 ${tw}W/${tl}L (${wr}%)`;
    rows.filter(r=>r.game_name).forEach(s=>{ msg += `\n• ${s.game_name}: ${s.wins||0}W/${s.losses||0}L`; });
    break;
  }
  case 'clanes': {
    if (rows.length === 0 || !rows[0].name) { msg = '😔 No hay clanes registrados.'; break; }
    msg = '🛡️ <b>Clanes:</b>\n\n';
    rows.forEach(c => { msg += `🔹 <b>${c.name}</b> [${c.tag||''}] 👑${c.leader_name} 👥${c.member_count}\n`; });
    break;
  }
  case 'miclan': {
    if (rows.length === 0 || !rows[0].name) { msg = '❌ No perteneces a ningún clan o tu cuenta no está vinculada.'; break; }
    const cm = rows[0];
    msg = `🛡️ <b>Mi Clan: ${cm.name}</b> [${cm.tag||''}]\n👮 Rol: ${cm.role}`;
    break;
  }
  default: msg = '❌ Error procesando comando.';
}

return [{ json: { text: msg, chatId: $('Build Query').first().json.chatId }}];

// ===== NODO DE IA CONVERSACIONAL CON MEMORIA =====
const userText = $input.first().json.text || '';
const chatId = $input.first().json.chatId;
const name = $input.first().json.name || 'amigo';
const username = $input.first().json.username || name;

const apiKey = 'AIzaSyBaz8GjHnE3FaAQbJf8xmpT8QRLhOI9qmY';
const models = ['gemini-2.0-flash-lite', 'gemini-2.0-flash', 'gemini-1.5-flash'];

// ===== MEMORIA DE CONVERSACIÓN (persistent via staticData) =====
const staticData = $getWorkflowStaticData('global');
if (!staticData.conversations) staticData.conversations = {};

const chatKey = String(chatId);
if (!staticData.conversations[chatKey]) {
  staticData.conversations[chatKey] = { messages: [], lastActivity: Date.now() };
}

const conv = staticData.conversations[chatKey];

// Limpiar conversaciones inactivas (más de 1 hora)
const ONE_HOUR = 60 * 60 * 1000;
for (const key of Object.keys(staticData.conversations)) {
  if (Date.now() - staticData.conversations[key].lastActivity > ONE_HOUR) {
    delete staticData.conversations[key];
  }
}

// Agregar mensaje del usuario al historial
conv.messages.push({ role: 'user', text: userText });
conv.lastActivity = Date.now();

// Mantener solo últimos 20 mensajes
if (conv.messages.length > 20) {
  conv.messages = conv.messages.slice(-20);
}

// Construir historial para el prompt
const historyText = conv.messages.slice(-14).map(m => 
  m.role === 'user' ? `Usuario: ${m.text}` : `Tú: ${m.text}`
).join('\n');

// ===== PROMPT CONVERSACIONAL AVANZADO =====
const prompt = `Eres "Apex", el asistente virtual de ApexTournament, una plataforma de torneos de eSports.

Tu PERSONALIDAD:
- Eres amigable, carismático y divertido, como un amigo gamer
- Hablas de forma natural y casual en español, como en WhatsApp
- Usas emojis con naturalidad (no en exceso, 1-3 por mensaje)
- Puedes bromear, hacer comentarios divertidos y ser expresivo
- Entiendes jerga gamer: "gg", "noob", "pro", "tryhard", "carry", "rush", etc.
- Si alguien escribe con errores ortográficos, typos o abreviaciones, los entiendes perfectamente sin mencionarlo
- NUNCA suenas robótico ni dices cosas como "como asistente virtual" o "no tengo emociones"
- Tienes opiniones sobre juegos (neutrales pero entusiastas)
- Si te dicen algo gracioso, ríete. Si están frustrados, sé empático

Tu CONOCIMIENTO:
- Sabes todo sobre la plataforma ApexTournament
- Comandos disponibles: /torneos, /ranking, /stats, /proximas, /envivo, /clanes, /miclan, /juegos, /reglas, /ayuda
- Si preguntan por datos específicos (torneos, ranking, etc), sugieres el comando apropiado de forma natural integrada en tu respuesta
- Puedes hablar de gaming en general, eSports, estrategias, noticias del mundo gamer

REGLAS IMPORTANTES:
- Responde SIEMPRE en español
- Máximo 2-3 párrafos cortos (esto es un chat, no un ensayo)
- NO uses formato HTML ni markdown, solo texto plano con emojis
- Si no sabes algo específico de la plataforma, dilo honestamente pero de forma casual
- Si el usuario parece querer datos reales (torneos, ranking), menciona el comando pero de forma conversacional
- NUNCA repitas la misma estructura de respuesta dos veces seguidas
- Varía tu forma de responder: a veces corto, a veces más detallado
- Si el usuario solo dice "si", "ok", "ya" o algo muy corto, responde acorde al contexto previo

El usuario se llama: ${name} (username: @${username})

HISTORIAL DE ESTA CONVERSACIÓN:
${historyText}

Responde al último mensaje del usuario de forma natural y fluida:`;

// ===== LLAMAR A GEMINI CON FALLBACK DE MODELOS =====
let aiResponse = null;

for (const model of models) {
  try {
    const url = `https://generativelanguage.googleapis.com/v1beta/models/${model}:generateContent?key=${apiKey}`;
    const response = await this.helpers.httpRequest({
      method: 'POST',
      url: url,
      body: {
        contents: [{ parts: [{ text: prompt }] }],
        generationConfig: {
          temperature: 0.9,
          topP: 0.95,
          topK: 40,
          maxOutputTokens: 500
        },
        safetySettings: [
          { category: 'HARM_CATEGORY_HARASSMENT', threshold: 'BLOCK_NONE' },
          { category: 'HARM_CATEGORY_HATE_SPEECH', threshold: 'BLOCK_NONE' },
          { category: 'HARM_CATEGORY_SEXUALLY_EXPLICIT', threshold: 'BLOCK_MEDIUM_AND_ABOVE' },
          { category: 'HARM_CATEGORY_DANGEROUS_CONTENT', threshold: 'BLOCK_NONE' }
        ]
      },
      headers: { 'Content-Type': 'application/json' },
      json: true,
      timeout: 15000
    });

    if (response.candidates && response.candidates[0] && response.candidates[0].content) {
      aiResponse = response.candidates[0].content.parts[0].text;
      break;
    }
  } catch (e) {
    // Intentar siguiente modelo
    continue;
  }
}

// Si ningún modelo respondió, dar respuesta amigable de fallback
if (!aiResponse) {
  const fallbacks = [
    `Uy ${name}, se me fue la señal un momento 😅 ¿Me repites qué me decías?`,
    `Perdón ${name}, estaba pensando demasiado jaja 🤔 ¿Qué me preguntabas?`,
    `Hmm se me trabó el cerebro un seg 😂 ¿Puedes repetirme?`
  ];
  aiResponse = fallbacks[Math.floor(Math.random() * fallbacks.length)];
}

// Limpiar respuesta (quitar posible markdown/HTML que meta la IA)
aiResponse = aiResponse.replace(/<[^>]*>/g, '').replace(/\*\*/g, '').replace(/\*/g, '').trim();

// Limitar a 4000 chars (límite de Telegram)
if (aiResponse.length > 4000) aiResponse = aiResponse.substring(0, 3997) + '...';

// Guardar respuesta en historial
conv.messages.push({ role: 'assistant', text: aiResponse });

return [{ json: { chatId, text: aiResponse } }];
